\title{Periodic Orbits through the Logistic--Tent Conjugacy}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
The logistic map $f(x) = 4x(1-x)$ on the unit interval $[0,1]$ is the canonical
example of smooth one-dimensional chaos, while the tent map $T(t) = 1 - |2t-1|$
is its piecewise-linear analogue. We record and exploit an exact topological
conjugacy between the two, realised by the strictly increasing homeomorphism
$h(t) = \sin^2(\pi t/2)$ of $[0,1]$, which satisfies $f\circ h = h\circ T$ and
hence $f^{\,n}\circ h = h\circ T^{\,n}$ for every $n$. From this single identity
we derive the full transfer of the periodic-orbit structure: a periodic-point
equivalence, a bijection of periodic-point sets, an equal-cardinality counting
reduction, an exact computation of the logistic fixed set as $\{0,3/4\}$, and the
realisation of a period-three orbit which by Sharkovskii's theorem forces orbits
of every period. We close with the measure-theoretic and cryptographic
consequences of the bridge.
\end{abstract}

\maketitle

\section{Introduction}

Deterministic chaos on the interval is most often illustrated by the logistic
family $f_r(x) = r\,x(1-x)$ at the parameter $r = 4$, where the dynamics become
fully chaotic on $[0,1]$. The map's smoothness and quadratic nonlinearity give it
an aura of analytic difficulty: the $n$-fold iterate $f^{\,n}$ is a polynomial of
degree $2^n$, and counting its fixed points seems to require solving equations of
exploding degree. The tent map $T(t) = 1 - |2t-1|$ presents the opposite face: it
is piecewise linear, its $n$-fold iterate is a sawtooth of $2^n$ affine ramps, and
every question about it reduces to elementary arithmetic. The two maps are
nonetheless dynamically indistinguishable, being topologically conjugate through an
explicit, differentiable homeomorphism. This paper makes the consequences of that
conjugacy precise for the periodic-orbit structure, showing how the transcendental
fixed-point count for the smooth map collapses to a combinatorial count for the
linear one.

\section{Definitions and basic setup}

Throughout, all dynamics take place on the unit interval $[0,1]\subset\mathbb{R}$.

\begin{definition}[Logistic map]
The \emph{logistic map} at the fully chaotic parameter is $f(x) = 4x(1-x)$.
\end{definition}

\begin{definition}[Tent map]
The \emph{tent map} is $T(t) = 1 - |2t-1|$; explicitly $T(t) = 2t$ for
$t\le\tfrac12$ and $T(t) = 2-2t$ for $t\ge\tfrac12$.
\end{definition}

\begin{definition}[Conjugating coordinate]
The \emph{conjugating change of coordinates} is $h(t) = \sin^2(\pi t/2)$.
\end{definition}

\begin{definition}[Period-$n$ point]
A point $x\in[0,1]$ is a \emph{period-$n$ point} of a map $g$ if $g^{\,n}(x)=x$,
where $g^{\,n}$ is the $n$-fold composition. The period is \emph{exact} if in
addition $g^{\,k}(x)\ne x$ for all $1\le k<n$.
\end{definition}

\begin{lemma}[Invariance of the interval]
For $t\in[0,1]$ we have $T(t)\in[0,1]$ and $h(t)\in[0,1]$; consequently
$T^{\,n}(t)\in[0,1]$ for all $n$.
\end{lemma}

\begin{proof}
For the tent map, $|2t-1|\le 1$ when $0\le t\le 1$, so $T(t)=1-|2t-1|\in[0,1]$.
For $h$, the value $\sin^2(\pi t/2)$ lies in $[0,1]$ since $\sin\in[-1,1]$.
Interval-invariance of $T^{\,n}$ follows by induction on $n$.
\end{proof}

\section{The conjugacy}

\begin{theorem}[Topological conjugacy]
For all $t\in\mathbb{R}$, $\ f\big(h(t)\big) = h\big(T(t)\big)$.
\end{theorem}

\begin{proof}
Write $\theta=\pi t/2$. By the double-angle identity,
\[
f(h(t)) = 4\sin^2\theta\,(1-\sin^2\theta) = 4\sin^2\theta\cos^2\theta
= \sin^2(2\theta) = \sin^2(\pi t).
\]
Split on the tent's branches. If $t\le\tfrac12$, then $T(t)=2t$ and
$h(T(t))=\sin^2(\pi t)$. If $t>\tfrac12$, then $T(t)=2-2t$ and
$h(T(t))=\sin^2(\pi-\pi t)=\sin^2(\pi t)$, using $\sin(\pi-\alpha)=\sin\alpha$. In
both cases the sides agree.
\end{proof}

\begin{corollary}[Intertwining of iterates]
For every $n\in\mathbb{N}$ and all $t$, $\ f^{\,n}\big(h(t)\big) = h\big(T^{\,n}(t)\big)$.
\end{corollary}

\begin{proof}
Induction on $n$. The base $n=0$ is trivial. For the step,
$f^{\,n+1}(h(t)) = f\big(h(T^{\,n}(t))\big) = h\big(T^{\,n+1}(t)\big)$ by the
inductive hypothesis and the conjugacy identity.
\end{proof}

\begin{theorem}[$h$ is a homeomorphism of $[0,1]$]
The map $h$ is strictly increasing on $[0,1]$, hence injective there, and maps
$[0,1]$ onto $[0,1]$.
\end{theorem}

\begin{proof}
On $[0,1]$ the argument $\pi t/2$ ranges over $[0,\pi/2]$, where $\sin$ is strictly
increasing and non-negative; squaring preserves strict monotonicity, so $h$ is
strictly increasing and injective. Continuity of $h$ with $h(0)=0$ and
$h(1)=\sin^2(\pi/2)=1$ gives, by the intermediate value theorem, that the image is
all of $[0,1]$.
\end{proof}

In particular $h$ separates distinct seeds: if $a\ne b$ in $[0,1]$ then
$h(a)\ne h(b)$.

\section{Transfer of periodic points}

\begin{theorem}[Periodic-point equivalence]
For $t\in[0,1]$ and any $n$,
\[
f^{\,n}\big(h(t)\big) = h(t) \iff T^{\,n}(t) = t.
\]
\end{theorem}

\begin{proof}
$(\Leftarrow)$ If $T^{\,n}(t)=t$ then $f^{\,n}(h(t))=h(T^{\,n}(t))=h(t)$ by the
intertwining. $(\Rightarrow)$ If $f^{\,n}(h(t))=h(t)$ then
$h(T^{\,n}(t))=h(t)$; both $T^{\,n}(t)$ and $t$ lie in $[0,1]$ and $h$ is injective
there, so $T^{\,n}(t)=t$.
\end{proof}

\begin{theorem}[Bijection of periodic-point sets]
For every $n$, $h$ restricts to a bijection
\[
\{\,t\in[0,1]:T^{\,n}(t)=t\,\}\ \xrightarrow{\ \sim\ }\
\{\,x\in[0,1]:f^{\,n}(x)=x\,\}.
\]
\end{theorem}

\begin{proof}
By the equivalence and interval-invariance, $h$ maps the left set into the right
set, injectively. For surjectivity, if $f^{\,n}(x)=x$ pick $t\in[0,1]$ with
$h(t)=x$ (surjectivity of $h$); then $f^{\,n}(h(t))=h(t)$, so $T^{\,n}(t)=t$.
\end{proof}

\begin{corollary}[Counting reduction]
For every $n$,
\[
\#\{\,x\in[0,1]:f^{\,n}(x)=x\,\} = \#\{\,t\in[0,1]:T^{\,n}(t)=t\,\}.
\]
\end{corollary}

\begin{proof}
A bijection equates cardinalities.
\end{proof}

\section{The base of the exponential count}

\begin{theorem}[Logistic fixed set]
The fixed points of $f$ in $[0,1]$ are exactly $\{0,\tfrac34\}$.
\end{theorem}

\begin{proof}
$f(x)=x$ reads $4x(1-x)=x$, i.e. $x(4x-3)=0$, with roots $x=0$ and $x=\tfrac34$,
both in $[0,1]$.
\end{proof}

\begin{corollary}[Fixed-point count]
The logistic map has exactly $2=2^1$ fixed points in $[0,1]$.
\end{corollary}

The tent map likewise has two fixed points in $[0,1]$, namely $0$ and $\tfrac23$,
matched by the bijection. This is the base case of the conjectured general count.

\section{Realisation of period three}

\begin{lemma}[An explicit tent 3-cycle]
$T(\tfrac27)=\tfrac47$, $T(\tfrac47)=\tfrac67$, $T(\tfrac67)=\tfrac27$; hence
$T^{\,3}(\tfrac27)=\tfrac27$ and $\{\tfrac27,\tfrac47,\tfrac67\}$ is an orbit of
exact period three.
\end{lemma}

\begin{proof}
$T(\tfrac27)=2\cdot\tfrac27=\tfrac47$; $T(\tfrac47)=2-2\cdot\tfrac47=\tfrac67$;
$T(\tfrac67)=2-2\cdot\tfrac67=\tfrac27$. The three values are distinct.
\end{proof}

\begin{theorem}[Logistic period-three orbit]
The point $x_0=h(\tfrac27)=\sin^2(\pi/7)$ satisfies $f^{\,3}(x_0)=x_0$ while
$f(x_0)\ne x_0$ and $f^{\,2}(x_0)\ne x_0$; that is, $x_0$ has exact period three.
\end{theorem}

\begin{proof}
$f^{\,3}(x_0)=h(T^{\,3}(\tfrac27))=h(\tfrac27)=x_0$. Also $f(x_0)=h(\tfrac47)$ and
$f^{\,2}(x_0)=h(\tfrac67)$; since $\tfrac27,\tfrac47,\tfrac67$ are distinct and $h$
is injective, these differ from $x_0$.
\end{proof}

\begin{corollary}[Orbits of every period]
The logistic map has periodic orbits of every period $n\ge 1$.
\end{corollary}

\begin{proof}
$f$ is continuous and has an orbit of exact period three; Sharkovskii's theorem
then yields orbits of every period.
\end{proof}

\section{Discussion and applications}

The counting reduction converts a question about roots of degree-$2^n$ polynomials
into a question about crossings of a sawtooth, exactly and for all $n$
simultaneously. The full force of Sharkovskii's ordering is unlocked by a single
explicit rational cycle transported through $h$.

\textbf{Invariant measure.} The tent map preserves the uniform measure on $[0,1]$;
pushing this forward through $h$ under $x=\sin^2(\pi t/2)$ produces the arcsine
measure with density $\tfrac{1}{\pi\sqrt{x(1-x)}}$, the invariant density of the
logistic map.

\textbf{Cryptographic fragility.} Proposals to build stream ciphers from
``chaotic'' logistic keystreams fail against the conjugacy: any invariant an
attacker can extract has an exact counterpart in the tent coordinate obtained by
applying $h^{-1}$, where the dynamics is the binary shift map (one iteration
deletes the leading bit of the seed's binary expansion). Apparent complexity of the
parabola orbit is a coordinate artefact.

\section{Future work}

We conjecture that for every $n\ge1$ the tent map, and hence the logistic map, has
exactly $2^n$ points of period dividing $n$; the equal-cardinality reduction is
already in hand, leaving a combinatorial ramp-counting induction. We further
conjecture exact period $n$ for every $n$ (via dyadic-type rational seeds
$k/(2^n\pm1)$), density of periodic points and topological transitivity (inherited
from the tent map through the homeomorphism), and that the logistic map preserves
the arcsine measure as the pushforward of Lebesgue measure.

\section{Conclusion}

An explicit sine-squared change of coordinates identifies the smooth logistic map
with the piecewise-linear tent map as dynamical systems. The periodic-orbit
skeleton transfers verbatim: periodicity, period, and orbit count all match, the
fixed set is $\{0,3/4\}$, and a single rational three-cycle certifies orbits of
every period. Counting smooth periodic points becomes counting linear ones --- the
transcendental made combinatorial by a change of clothes.

\end{document}

