"""Verify the conjugacy identity f(h(t)) = h(T(t)) across the unit interval."""
from __future__ import annotations
import math


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)


def h(t: float) -> float:
    return math.sin(math.pi * t / 2.0) ** 2


def verify_conjugacy(num_samples: int = 21) -> float:
    max_err = 0.0
    for i in range(num_samples):
        t = i / (num_samples - 1)
        lhs, rhs = logistic(h(t)), h(tent(t))
        max_err = max(max_err, abs(lhs - rhs))
        print(f"t={t:.3f}  f(h(t))={lhs:.12f}  h(T(t))={rhs:.12f}")
    print(f"maximum discrepancy: {max_err:.2e}")
    return max_err


if __name__ == "__main__":
    verify_conjugacy()

"""Transport the tent 3-cycle 2/7 -> 4/7 -> 6/7 to a logistic period-three orbit."""
from __future__ import annotations
import math
from typing import Callable, List


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)


def h(t: float) -> float:
    return math.sin(math.pi * t / 2.0) ** 2


def iterate(g: Callable[[float], float], n: int, x: float) -> float:
    for _ in range(n):
        x = g(x)
    return x


def show_period_three() -> List[float]:
    tent_seed = 2 / 7
    print("tent cycle:", [round(iterate(tent, k, tent_seed), 6) for k in range(4)])
    x0 = h(tent_seed)
    orbit = [iterate(logistic, k, x0) for k in range(3)]
    print("logistic seed x0 = sin^2(pi/7) =", x0)
    print("logistic orbit:", orbit)
    print("f^3(x0) =", iterate(logistic, 3, x0), "(== x0)")
    assert len({round(v, 9) for v in orbit}) == 3, "orbit must have 3 distinct points"
    return orbit


if __name__ == "__main__":
    show_period_three()

"""Empirically confirm the logistic map preserves the arcsine measure."""
from __future__ import annotations
import math
from typing import List


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def arcsine_mass(a: float, b: float) -> float:
    """Mass of density 1/(pi sqrt(x(1-x))) on [a,b]."""
    return (2.0 / math.pi) * (math.asin(math.sqrt(b)) - math.asin(math.sqrt(a)))


def histogram_vs_arcsine(num_iters: int = 500_000, bins: int = 20) -> List[float]:
    x = 0.234123
    hist = [0] * bins
    for _ in range(num_iters):
        x = logistic(x)
        hist[min(bins - 1, int(x * bins))] += 1
    errors = []
    for i in range(bins):
        a, b = i / bins, (i + 1) / bins
        emp, theo = hist[i] / num_iters, arcsine_mass(a, b)
        errors.append(abs(emp - theo))
        print(f"[{a:.2f},{b:.2f})  empirical={emp:.4f}  arcsine={theo:.4f}")
    print("max bin error:", max(errors))
    return errors


if __name__ == "__main__":
    histogram_vs_arcsine()

