from __future__ import annotations
from typing import Callable


def tent(t: float) -> float:
    return 1.0 - abs(2.0 * t - 1.0)


def logistic(x: float) -> float:
    return 4.0 * x * (1.0 - x)


def iterate(g: Callable[[float], float], n: int, x: float) -> float:
    for _ in range(n):
        x = g(x)
    return x


def count_period_n_points(g: Callable[[float], float], n: int,
                          grid: int = 200_000) -> int:
    """Count period-n points of g on [0,1] via diagonal crossings of g^n - id.

    By the conjugacy, the count is the same for the tent and logistic maps and
    equals 2^n. This routine estimates it by detecting sign changes of
    g^n(x) - x on a fine grid.
    """
    def gn(x: float) -> float:
        return iterate(g, n, x) - x

    count = 0
    prev = gn(0.0)
    if abs(prev) < 1e-12:
        count += 1
    for i in range(1, grid + 1):
        cur = gn(i / grid)
        if prev != 0.0 and ((prev < 0.0 <= cur) or (prev > 0.0 >= cur)):
            count += 1
        if cur != 0.0:
            prev = cur
    return count


if __name__ == "__main__":
    for n in range(1, 7):
        print(n, count_period_n_points(tent, n), count_period_n_points(logistic, n), 2 ** n)
